Tentu, ini kode Node.js menggunakan axios untuk melakukan permintaan POST ke URL yang Anda berikan:

```javascript
const axios = require("axios");

async function getData(urlInput) {
  try {
    const response = await axios.post(
      "https://hentai-cosplay-xxx.com/",
      {
        url: urlInput
      },
      {
        headers: {
          "Content-Type": "application/json"
        }
      }
    );

    return response.data;
  } catch (error) {
    return {
      error: error.message
    };
  }
}

getData("https://hentai-cosplay-xxx.com/")
  .then(result => m.reply(JSON.stringify(result, null, 2)))
  .catch(error => m.reply(error.message));
```
